import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadOswald = makeLoadFont('Oswald');
const loadRobotoMono = makeLoadFont('RobotoMono');

// Load clean sans-serif and monospace fonts at module level for robust rendering
const { fontFamily: oswaldFamily } = loadOswald();
const { fontFamily: robotoMonoFamily } = loadRobotoMono();

// Helper to generate a realistic vertical ticket path with rounded top corners and a jagged/perforated bottom edge
const getParkingTicketPath = (w: number, h: number, r: number) => {
  const numTeeth = 24;
  const toothWidth = w / numTeeth;
  const toothHeight = 8;
  
  let path = `M ${r} 0 L ${w - r} 0 A ${r} ${r} 0 0 1 ${w} ${r} L ${w} ${h - toothHeight}`;
  
  // Jagged bottom teeth (perforations)
  for (let i = 0; i < numTeeth; i++) {
    const xMid = w - ((i + 0.5) * toothWidth);
    const xEnd = w - ((i + 1) * toothWidth);
    path += ` L ${xMid} ${h} L ${xEnd} ${h - toothHeight}`;
  }
  
  path += ` L 0 ${r} A ${r} ${r} 0 0 1 ${r} 0 Z`;
  return path.replace(/\s+/g, " ").trim();
};



export type TicketAnimationProps = Record<string, any>;

// Detailed Monospace Barcode SVG component
const MockBarcode: React.FC<{
  w: number;
  h: number;
  color: string;
  code: string;
  fontFamily: string;
}> = ({ w, h, color, code, fontFamily }) => {
  const barWidths = [
    2, 1, 3, 1, 4, 2, 1, 3, 2, 1, 4, 1, 2, 3, 1, 4, 2, 1, 
    3, 2, 1, 4, 1, 2, 3, 1, 4, 2, 1, 3, 1, 2, 4, 1, 3, 2, 
    1, 4, 2, 1, 3, 1, 2, 4, 1
  ];
  const totalWeight = barWidths.reduce((sum, val) => sum + val, 0);
  const scale = w / totalWeight;

  let currentX = 0;
  return (
    <g>
      {barWidths.map((weight, i) => {
        const width = weight * scale;
        const fill = i % 2 === 0 ? color : "transparent";
        const x = currentX;
        currentX += width;
        if (fill === "transparent") return null;
        return (
          <rect
            key={i}
            x={x}
            y={0}
            width={width - 0.2}
            height={h * 0.7}
            fill={color}
          />
        );
      })}
      <text
        x={w / 2}
        y={h}
        fill={color}
        fontFamily={fontFamily}
        fontSize={h * 0.22}
        textAnchor="middle"
        letterSpacing={3}
      >
        {code}
      </text>
    </g>
  );
};

