export const TicketAnimation: React.FC<TicketAnimationProps> = ({
  backgroundColor = "#0b0f19",
  transparentBackground = true,
  durationInSeconds = 6,
  ticketScale = 1.1,
  staggerDelay = 12,

  // Front Ticket Default Values (Red Citation)
  frontTitle = "CITY DEPT OF TRAFFIC",
  frontSubtitle = "VIOLATION NOTICE",
  frontFine = "$125.00",
  frontViolation = "EXPIRED METER ZONE 03",
  frontPlate = "PLATE: 8TRK209",
  frontCitationNumber = "C-4892-0941",
  frontColor = "#fff9db",
  frontHeaderColor = "#e63946",
  frontTextColor = "#1d3557",

  // Back Ticket Default Values (Orange Warning)
  backTitle = "STATE PARKING SERVICE",
  backSubtitle = "WARNING CITATION",
  backFine = "$0.00",
  backViolation = "OVERTIME STALL COMPLIANCE",
  backPlate = "PLATE: 8TRK209",
  backCitationNumber = "W-2941-8931",
  backColor = "#ffffff",
  backHeaderColor = "#f4a261",
  backTextColor = "#264653",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Dynamic vertical-format ticket dimensions optimized for 9:16 layout space
  const ticketWidth = width * 0.48;
  const ticketHeight = ticketWidth * 1.85;

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Spring physics configurations for sequential entry animation
  const backSpring = spring({
    frame: frame - 12,
    fps,
    config: { damping: 13, mass: 0.8, stiffness: 85 },
  });

  const frontSpring = spring({
    frame: frame - (12 + staggerDelay),
    fps,
    config: { damping: 11, mass: 0.9, stiffness: 80 },
  });

  // Hover floating offset vectors to maintain continuous organic movement
  const backHoverY = Math.sin(frame * 0.04) * 8;
  const backHoverX = Math.cos(frame * 0.035) * 6;
  const backHoverRot = Math.cos(frame * 0.045) * 0.4;

  const frontHoverY = Math.cos(frame * 0.045) * 10;
  const frontHoverX = Math.sin(frame * 0.04) * 8;
  const frontHoverRot = Math.sin(frame * 0.05) * 0.5;

  // Back Ticket translation and alignment calculations
  const backScaleVal = interpolate(backSpring, [0, 1], [0.4, ticketScale], {
    extrapolateRight: "clamp",
  });
  const backTx = interpolate(backSpring, [0, 1], [-width * 0.08, 0], {
    extrapolateRight: "clamp",
  }) + backHoverX;
  const backTy = interpolate(backSpring, [0, 1], [height * 0.2, 0], {
    extrapolateRight: "clamp",
  }) + backHoverY;
  const backRotate = interpolate(backSpring, [0, 1], [-30, -7], {
    extrapolateRight: "clamp",
  }) + backHoverRot;
  const backOpacity = interpolate(frame, [12, 22], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Front Ticket translation and alignment calculations
  const frontScaleVal = interpolate(frontSpring, [0, 1], [0.4, ticketScale], {
    extrapolateRight: "clamp",
  });
  const frontTx = interpolate(frontSpring, [0, 1], [width * 0.08, 0], {
    extrapolateRight: "clamp",
  }) + frontHoverX;
  const frontTy = interpolate(frontSpring, [0, 1], [height * 0.2, 0], {
    extrapolateRight: "clamp",
  }) + frontHoverY;
  const frontRotate = interpolate(frontSpring, [0, 1], [25, 4], {
    extrapolateRight: "clamp",
  }) + frontHoverRot;
  const frontOpacity = interpolate(
    frame,
    [12 + staggerDelay, 12 + staggerDelay + 10],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  const backStyle: React.CSSProperties = {
    position: "absolute",
    width: ticketWidth,
    height: ticketHeight,
    left: width / 2 - ticketWidth / 2,
    top: height / 2 - ticketHeight / 2 - height * 0.03,
    transform: `scale(${backScaleVal}) translate(${backTx}px, ${backTy}px) rotate(${backRotate}deg)`,
    opacity: backOpacity,
    transformOrigin: "center center",
    transition: "none",
  };

  const frontStyle: React.CSSProperties = {
    position: "absolute",
    width: ticketWidth,
    height: ticketHeight,
    left: width / 2 - ticketWidth / 2,
    top: height / 2 - ticketHeight / 2 + height * 0.03,
    transform: `scale(${frontScaleVal}) translate(${frontTx}px, ${frontTy}px) rotate(${frontRotate}deg)`,
    opacity: frontOpacity,
    transformOrigin: "center center",
    transition: "none",
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      {/* Back Ticket (Warning Citation) */}
      <div style={backStyle}>
        <ParkingTicket
          id="back"
          w={ticketWidth}
          h={ticketHeight}
          ticketColor={backColor}
          headerColor={backHeaderColor}
          textColor={backTextColor}
          title={backTitle}
          subtitle={backSubtitle}
          fine={backFine}
          violation={backViolation}
          plate={backPlate}
          citationNumber={backCitationNumber}
          titleFont={oswaldFamily}
          monoFont={robotoMonoFamily}
        />
      </div>

      {/* Front Ticket (Violation Notice) */}
      <div style={frontStyle}>
        <ParkingTicket
          id="front"
          w={ticketWidth}
          h={ticketHeight}
          ticketColor={frontColor}
          headerColor={frontHeaderColor}
          textColor={frontTextColor}
          title={frontTitle}
          subtitle={frontSubtitle}
          fine={frontFine}
          violation={frontViolation}
          plate={frontPlate}
          citationNumber={frontCitationNumber}
          titleFont={oswaldFamily}
          monoFont={robotoMonoFamily}
        />
      </div>
    </AbsoluteFill>
  );
};

export default TicketAnimation;